import { Link, useLocation, useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import { useState } from "react";
import { useAuth } from "../context/AuthContext";
import "../App.css";

function Navbar() {
  const location = useLocation();
  const navigate = useNavigate();
  const { user, logout, isAuthenticated, isAdmin } = useAuth();
  const [showProfileMenu, setShowProfileMenu] = useState(false);

  // 현재 경로가 활성 메뉴인지 확인
  const isActive = (path) => {
    return location.pathname === path;
  };

  // 로그아웃 처리
  const handleLogout = () => {
    if (window.confirm("로그아웃 하시겠습니까?")) {
      logout();
      navigate("/");
      alert("로그아웃 되었습니다.");
      setShowProfileMenu(false);
    }
  };

  return (
    <motion.nav
      style={{
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center",
        background: "#000",
        padding: "20px 80px",
        boxShadow: "0 2px 20px rgba(0, 0, 0, 0.3)",
        position: "sticky",
        top: 0,
        zIndex: 1000,
        borderBottom: "1px solid rgba(255, 255, 255, 0.1)",
      }}
      initial={{ y: -100 }}
      animate={{ y: 0 }}
      transition={{ duration: 0.5, ease: "easeOut" }}
    >
      {/* Logo */}
      <Link to="/" style={{ textDecoration: "none" }}>
        <motion.div style={{ display: "flex", alignItems: "center", gap: "12px" }}>
          <div
            style={{
              width: "40px",
              height: "40px",
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              borderRadius: "8px",
              boxShadow: "0 4px 12px rgba(255, 107, 53, 0.3)",
            }}
          >
            <span style={{ color: "#fff", fontSize: "22px", fontWeight: "800" }}>A</span>
          </div>
          <span style={{ fontSize: "24px", fontWeight: "700", color: "#fff" }}>ASSEMBLE</span>
        </motion.div>
      </Link>

      {/* Navigation Menu */}
      <ul
        style={{
          display: "flex",
          gap: "50px",
          listStyle: "none",
          margin: 0,
          padding: 0,
          alignItems: "center",
        }}
      >
        {[
          { path: "/projects", label: "My Project" },
          { path: "/resources", label: "Resources" },
          { path: "/library", label: "Library" },
          { path: "/about", label: "About Us" },
          ...(isAdmin ? [{ path: "/admin", label: "Admin" }] : []),
        ].map((item) => (
          <li key={item.path}>
            <Link to={item.path} style={{ textDecoration: "none" }}>
              <motion.div
                style={{
                  fontSize: "15px",
                  fontWeight: isActive(item.path) ? 600 : 500,
                  color: isActive(item.path) ? "#ff6b35" : "#fff",
                  cursor: "pointer",
                  transition: "all 0.3s ease",
                  opacity: isActive(item.path) ? 1 : 0.7,
                  position: "relative",
                  paddingBottom: isActive(item.path) ? "4px" : "0",
                  borderBottom: isActive(item.path) ? "2px solid #ff6b35" : "none",
                }}
                whileHover={{
                  opacity: 1,
                }}
              >
                {item.label}
              </motion.div>
            </Link>
          </li>
        ))}
      </ul>

      {/* Login/Logout Button */}
      {isAuthenticated ? (
        <div style={{ display: "flex", gap: "16px", alignItems: "center" }}>
          <span style={{ 
            color: "#fff", 
            fontSize: "15px", 
            fontWeight: "500",
            opacity: 0.9
          }}>
            {user?.username}님
          </span>
          <div style={{ position: "relative" }}>
            <button
              onClick={() => setShowProfileMenu(!showProfileMenu)}
              style={{
                background: "rgba(255, 255, 255, 0.1)",
                border: "1px solid rgba(255, 255, 255, 0.2)",
                cursor: "pointer",
                display: "flex",
                alignItems: "center",
                gap: "8px",
                fontSize: "15px",
                color: "#fff",
                fontWeight: "500",
                padding: "10px 18px",
                borderRadius: "8px",
                transition: "all 0.3s ease",
              }}
              onMouseEnter={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.15)";
              }}
              onMouseLeave={(e) => {
                e.currentTarget.style.background = "rgba(255, 255, 255, 0.1)";
              }}
            >
              <span style={{ fontSize: "20px" }}>🔑☑️</span>
              My Profile
            </button>
            {showProfileMenu && (
              <div style={{
                position: "absolute",
                top: "calc(100% + 8px)",
                right: 0,
                background: "#1a1a1a",
                border: "1px solid rgba(255, 255, 255, 0.15)",
                borderRadius: "10px",
                padding: "8px",
                boxShadow: "0 8px 32px rgba(0,0,0,0.5)",
                minWidth: "140px"
              }}>
                <button 
                  onClick={handleLogout}
                  style={{
                    width: "100%",
                    padding: "12px 16px",
                    background: "#ff6b35",
                    border: "none",
                    textAlign: "center",
                    cursor: "pointer",
                    fontSize: "15px",
                    color: "#fff",
                    borderRadius: "8px",
                    transition: "all 0.2s ease",
                    fontWeight: "600",
                  }}
                  onMouseEnter={(e) => {
                    e.currentTarget.style.background = "#ff4d00";
                    e.currentTarget.style.transform = "translateY(-2px)";
                  }}
                  onMouseLeave={(e) => {
                    e.currentTarget.style.background = "#ff6b35";
                    e.currentTarget.style.transform = "translateY(0)";
                  }}
                >
                  Logout
                </button>
              </div>
            )}
          </div>
        </div>
      ) : (
        <Link to="/login" style={{ textDecoration: "none" }}>
          <motion.button
            style={{
              padding: "10px 28px",
              border: "none",
              borderRadius: "12px",
              background: "linear-gradient(135deg, #ff6b35 0%, #ff4d00 100%)",
              color: "#fff",
              fontSize: "15px",
              fontWeight: 700,
              cursor: "pointer",
              boxShadow: "0 4px 15px rgba(255, 107, 53, 0.3)",
              transition: "all 0.3s ease",
            }}
            whileHover={{
              scale: 1.05,
              boxShadow: "0 6px 20px rgba(255, 107, 53, 0.4)",
            }}
            whileTap={{ scale: 0.95 }}
          >
            Login
          </motion.button>
        </Link>
      )}
    </motion.nav>
  );
}

export default Navbar;
